prs = {
    'fix-parser': {'files': ['pipelines/clean.py'], 'reviews': ['approve'], 'checks': {'test': 'pass'}},
    'docs-typo': {'files': ['README.md'], 'reviews': ['approve'], 'checks': {'test': 'pass'}},
    'new-load': {'files': ['pipelines/load.py', 'tests/test_load.py'], 'reviews': ['approve', 'approve', 'request_changes'], 'checks': {}},
    'lint-only': {'files': ['setup.cfg'], 'reviews': [], 'checks': {'test': 'fail'}},
}

for name, pr in prs.items():
    need = 2 if any(f.startswith('pipelines/') for f in pr['files']) else 1
    have = pr['reviews'].count('approve')
    reasons = []
    if have < need:
        reasons.append(f'approvals {have}/{need}')
    status = pr['checks'].get('test', 'missing')
    if status != 'pass':
        reasons.append(f'test {status}')
    if 'request_changes' in pr['reviews']:
        reasons.append('changes requested')
    print(f"{name}: MERGE" if not reasons else f"{name}: BLOCKED ({', '.join(reasons)})")
